  "inlineSchema": "// ===============================\n// PRISMA CONFIG\n// ===============================\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ===============================\n// ENUMS\n// ===============================\nenum Role {\n  admin\n  manager\n  customer\n}\n\nenum ProductKind {\n  apparel // roupa\n  shoes // calçado\n  accessory // acessórios\n}\n\nenum Target {\n  men\n  women\n  unisex\n}\n\nenum SizeSystem {\n  alpha // XS,S,M,L,XL...\n  EU // 36..46\n  US\n  UK\n}\n\n// ===============================\n// UTILIZADORES & MORADAS\n// ===============================\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  role      Role     @default(customer)\n  name      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  addresses Address[]\n  carts     Cart[]\n  orders    Order[]\n  reviews   Review[]\n  auditLogs AuditLog[]\n  wishlists Wishlist[]\n}\n\nmodel Address {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  type       String // \"shipping\" | \"billing\"\n  line1      String\n  line2      String?\n  city       String\n  postalCode String\n  country    String\n  createdAt  DateTime @default(now())\n}\n\n// ===============================\n// CATÁLOGO\n// ===============================\nmodel Category {\n  id       String     @id @default(cuid())\n  name     String\n  slug     String     @unique\n  parentId String?\n  parent   Category?  @relation(\"CategoryChildren\", fields: [parentId], references: [id])\n  children Category[] @relation(\"CategoryChildren\")\n  products Product[]\n}\n\nmodel Product {\n  id          String  @id @default(cuid())\n  name        String\n  slug        String  @unique\n  description String?\n  active      Boolean @default(true)\n\n  kind      ProductKind @default(apparel) // roupa, calçado, acessório\n  target    Target      @default(unisex) // homem, mulher, unissex\n  sizeGuide Json? // guia/tabela de tamanhos opcional\n\n  categoryId String?\n  category   Category? @relation(fields: [categoryId], references: [id])\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  variants ProductVariant[]\n  images   ProductImage[]\n  tags     ProductTag[]\n\n  // back-relations necessários para Review/Wishlist\n  reviews   Review[]\n  wishlists Wishlist[]\n\n  @@index([kind])\n  @@index([target])\n}\n\nmodel ProductVariant {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  sku        String @unique\n  priceCents Int\n  stock      Int\n\n  promoPriceCents Int?\n\n  color      String?\n  size       String?\n  sizeSystem SizeSystem?\n\n  attrs Json\n\n  cartItems  CartItem[]\n  orderItems OrderItem[]\n  images     VariantImage[]\n\n  @@unique([productId, color, size])\n  @@index([productId])\n  @@index([color])\n  @@index([size])\n}\n\nmodel VariantImage {\n  id        String         @id @default(cuid())\n  variantId String\n  variant   ProductVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  url       String\n  alt       String?\n  sort      Int            @default(0)\n\n  @@index([variantId])\n}\n\nmodel ProductImage {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  url       String\n  alt       String?\n  sort      Int     @default(0)\n\n  @@index([productId])\n}\n\nmodel ProductTag {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  tag       String\n\n  @@index([tag])\n  @@index([productId])\n}\n\n// ===============================\n// CARRINHO & CUPÕES\n// ===============================\nmodel Cart {\n  id        String     @id @default(cuid())\n  userId    String?\n  user      User?      @relation(fields: [userId], references: [id], onDelete: SetNull)\n  sessionId String?    @unique // visitante\n  items     CartItem[]\n  updatedAt DateTime   @updatedAt\n\n  @@index([userId])\n}\n\nmodel CartItem {\n  id         String         @id @default(cuid())\n  cartId     String\n  cart       Cart           @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  variantId  String\n  variant    ProductVariant @relation(fields: [variantId], references: [id])\n  qty        Int\n  priceCents Int // fotografia do preço na adição\n\n  @@index([cartId])\n  @@index([variantId])\n}\n\nmodel Coupon {\n  id       String    @id @default(cuid())\n  code     String    @unique\n  type     String // \"percent\" | \"fixed\"\n  value    Int // percent: 0-100; fixed: cents\n  startsAt DateTime?\n  endsAt   DateTime?\n  maxUses  Int?\n  used     Int       @default(0)\n  active   Boolean   @default(true)\n}\n\n// ===============================\n// PEDIDOS & PAGAMENTOS\n// ===============================\nmodel Order {\n  id         String      @id @default(cuid())\n  userId     String\n  user       User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  status     String      @default(\"pending\") // pending | awaiting_payment | paid | shipped | canceled\n  totalCents Int\n  shipping   Json // snapshot da morada de entrega\n  billing    Json // snapshot da morada de faturação\n  couponCode String?\n  paymentRef String?     @unique // Stripe PaymentIntent id (idempotência)\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n  items      OrderItem[]\n\n  @@index([userId, createdAt])\n  @@index([status])\n}\n\nmodel OrderItem {\n  id         String         @id @default(cuid())\n  orderId    String\n  order      Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  variantId  String\n  variant    ProductVariant @relation(fields: [variantId], references: [id])\n  qty        Int\n  priceCents Int // preço travado no momento\n\n  @@index([orderId])\n  @@index([variantId])\n}\n\n// ===============================\n// AUDITORIA & ENGAJAMENTO\n// ===============================\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  action    String // e.g., \"ORDER_STATUS_UPDATE\", \"STOCK_ADJUST\"\n  entity    String // \"Order\" | \"Product\" | \"Coupon\" | ...\n  entityId  String\n  meta      Json\n  createdAt DateTime @default(now())\n\n  @@index([entity, entityId])\n}\n\nmodel Review {\n  id        String   @id @default(cuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  rating    Int\n  text      String?\n  approved  Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@unique([productId, userId])\n  @@index([productId])\n  @@index([userId])\n}\n\nmodel Wishlist {\n  id        String  @id @default(cuid())\n  userId    String\n  user      User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, productId])\n  @@index([productId])\n}\n",
